/**
 * Milestone rows and the issue counts behind their progress.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, toMilestone
 */
import { and, count, eq, inArray, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of the project, closed ones included, for name checks and listing. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(input: {
  orgId: OrgId;
  milestoneId: MilestoneId;
  name?: string;
  targetDate?: IsoTimestamp | null;
}): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes a milestone and moves its open live issues in one transaction, so a
 * failure part-way leaves neither a half-moved set nor a closed milestone with
 * issues still pointing at it. Returns the ids that moved.
 */
export function closeMilestoneMovingIssues(input: {
  orgId: OrgId;
  milestoneId: MilestoneId;
  moveTo: MilestoneId | null;
}): { milestone: Milestone; movedIssueIds: readonly IssueId[] } {
  const db = getDb();
  return db.transaction((tx) => {
    const openIssues = tx
      .select({ id: issues.id })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.milestoneId, input.milestoneId),
          isNull(issues.archivedAt),
          sql`${issues.status} NOT IN (${sql.join(
            CLOSED_ISSUE_STATUSES.map((status) => sql`${status}`),
            sql`, `,
          )})`,
        ),
      )
      .all()
      .map((row) => row.id as IssueId);

    if (openIssues.length > 0) {
      tx.update(issues)
        .set({ milestoneId: input.moveTo, updatedAt: toIsoTimestamp(new Date()) })
        .where(
          and(
            orgPredicate(issues.orgId, input.orgId),
            inArray(issues.id, openIssues),
          ),
        )
        .run();
    }

    const row = tx
      .update(milestones)
      .set({
        closedAt: toIsoTimestamp(new Date()),
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(
        and(
          orgPredicate(milestones.orgId, input.orgId),
          eq(milestones.id, input.milestoneId),
        ),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
    return { milestone: toMilestone(row), movedIssueIds: openIssues };
  });
}

/**
 * Progress for every milestone of a project in one grouped query, keyed by
 * milestone id. Only live issues count; `closed` means done or canceled.
 */
export async function progressByMilestone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
        sql`${issues.milestoneId} IS NOT NULL`,
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const byMilestone = new Map<MilestoneId, { total: number; open: number; closed: number }>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const id = row.milestoneId as MilestoneId;
    const tally = byMilestone.get(id) ?? { total: 0, open: 0, closed: 0 };
    tally.total += row.value;
    if ((CLOSED_ISSUE_STATUSES as readonly string[]).includes(row.status)) {
      tally.closed += row.value;
    } else {
      tally.open += row.value;
    }
    byMilestone.set(id, tally);
  }
  return byMilestone;
}
