/**
 * Milestone lifecycle inside a project: create, rename or re-date, close (moving open issues out), reopen, and progress reads.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, requireFound
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId, IssueId } from "@/types/common";
import type { Milestone, MilestoneProgress, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";
import type { Actor } from "@/types/member";

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/** Creates a milestone in an open-to-use project; names are unique per project. */
export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const existing = await milestoneRepo.listMilestonesForProject(
    input.orgId,
    project.id,
  );
  assertNameFree(existing, input.name);
  assertRoomForAnotherOpen(existing);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name.trim(),
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates a milestone, open or closed. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone, project } = await authorizeMilestone(
    actor,
    input.orgId,
    input.milestoneId,
    "project:update",
  );
  assertNotArchived("Project", project.id, project);

  if (input.name !== undefined) {
    assertNameFree(
      await milestoneRepo.listMilestonesForProject(input.orgId, project.id),
      input.name,
      milestone.id,
    );
  }

  return milestoneRepo.updateMilestone({
    orgId: input.orgId,
    milestoneId: milestone.id,
    name: input.name?.trim(),
    targetDate: input.targetDate,
  });
}

/**
 * Closes a milestone. Its open live issues go to `moveOpenIssuesTo` (another
 * open milestone of the same project) or out of any milestone when that is
 * null. Done, canceled and archived issues stay where they are.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const { milestone, project } = await authorizeMilestone(
    actor,
    input.orgId,
    input.milestoneId,
    "project:update",
  );
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const target = input.moveOpenIssuesTo;
  if (target !== null) {
    if (target === milestone.id) throw new NotFoundError("Milestone", target);

    const next = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, target),
      "Milestone",
      target,
    );
    if (next.projectId !== project.id) {
      throw new NotFoundError("Milestone", target);
    }
    if (next.closedAt !== null) throw new MilestoneStateError("closed");
  }

  const { milestone: closed, movedIssueIds } =
    milestoneRepo.closeMilestoneMovingIssues({
      orgId: input.orgId,
      milestoneId: milestone.id,
      moveTo: target,
    });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: target,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

/** Reopens a closed milestone, subject to the open-milestone cap. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone, project } = await authorizeMilestone(
    actor,
    orgId,
    milestoneId,
    "project:update",
  );
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");

  assertRoomForAnotherOpen(
    await milestoneRepo.listMilestonesForProject(orgId, project.id),
  );

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Every milestone of a project with its progress, open ones first. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const now = Date.now();
  const milestones = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const progress = await milestoneRepo.progressByMilestone(orgId, projectId);

  return [...milestones]
    .sort(compareMilestones)
    .map((milestone) =>
      withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now),
    );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  const { milestone, project } = await authorizeMilestone(
    actor,
    orgId,
    milestoneId,
    "project:read",
  );

  const progress = await milestoneRepo.progressByMilestone(orgId, project.id);
  return withProgress(
    milestone,
    progress.get(milestone.id) ?? NO_PROGRESS,
    Date.now(),
  );
}

/** Loads a milestone and its project inside the actor's workspace, then checks `action` on the project. */
async function authorizeMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
  action: "project:read" | "project:update",
): Promise<{ milestone: Milestone; project: Project }> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, action, projectResource(project));

  return { milestone, project };
}

function assertNameFree(
  existing: readonly Milestone[],
  name: string,
  exceptId: MilestoneId | null = null,
): void {
  const key = milestoneNameKey(name);
  const taken = existing.some(
    (milestone) =>
      milestone.id !== exceptId && milestoneNameKey(milestone.name) === key,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

function assertRoomForAnotherOpen(existing: readonly Milestone[]): void {
  const open = existing.filter((milestone) => milestone.closedAt === null).length;
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

/** Open before closed; then by target date, earliest first, undated last; then oldest first. */
function compareMilestones(a: Milestone, b: Milestone): number {
  const openOrder = Number(a.closedAt !== null) - Number(b.closedAt !== null);
  if (openOrder !== 0) return openOrder;

  const aDue = a.targetDate === null ? Infinity : Date.parse(a.targetDate);
  const bDue = b.targetDate === null ? Infinity : Date.parse(b.targetDate);
  if (aDue !== bDue) return aDue < bDue ? -1 : 1;

  return a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id);
}

/** Overdue: open, dated strictly before `now`, and still holding open issues. */
function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: number,
): MilestoneWithProgress {
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < now &&
    progress.open > 0;

  return { milestone, progress, overdue };
}
