 * Milestone lifecycle: name uniqueness, the open cap, closing with an issue
 * move, the refusals that leave state untouched, and progress/overdue reads.
 */
import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { vi } from "vitest";
