import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { IsoTimestamp, MilestoneId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

const PAST = "2001-01-01T00:00:00.000Z" as IsoTimestamp;
const FUTURE = "2999-01-01T00:00:00.000Z" as IsoTimestamp;

describe("services/milestone-service", () => {
  it("refuses a name already used in the project, ignoring case and spaces", async () => {
    const tenant = await createTenant("msname", "growth");
    const { member } = tenant.actors;

    await milestoneService.createMilestone(member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: "Beta",
      targetDate: null,
    });

    await expect(
      milestoneService.createMilestone(member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "  beta ",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });
  });

